// instanceSteps returns the approval steps an in-flight instance must follow.
//
// The steps are snapshotted into workflow_instances.context when the request is
// submitted. Reading the live definition instead lets an administrator editing a
// workflow change the rules under approvals that are already in flight: removing
// a step strands them past the end of the list where no action is accepted, and
// reordering steps hands the decision to the wrong role. The snapshot is
// authoritative; the definition is only a fallback for rows written without one.
func instanceSteps(snapshot, definition []byte) []map[string]any {
	var context struct {
		Steps []map[string]any `json:"steps"`
	}
	if len(snapshot) > 0 && json.Unmarshal(snapshot, &context) == nil && len(context.Steps) > 0 {
		return context.Steps
	}
	var steps []map[string]any
	_ = json.Unmarshal(definition, &steps)
	return steps
}

// separationOfDuties is the `workflow.separation_of_duties` setting. It defaults
// to off so that upgrading cannot stall an approval an organisation already
// routes back to its requester, but procurement controls usually want it on.
type separationOfDuties struct {
	BlockSelfApproval bool `json:"blockSelfApproval"`
}

// Unlike the login and password policies, this one has no safe value to start
// from: its zero value permits self-approval. Reading it as "not configured"
// whenever the lookup failed would switch the control off at the moment it
// matters, so a failure is returned instead. A missing row still means the
// documented default, which is what a fresh install has.
func (a *App) separationOfDuties(ctx context.Context) (separationOfDuties, error) {
	var policy separationOfDuties
	var value []byte
	switch err := a.db.QueryRow(ctx, `SELECT value FROM settings WHERE key='workflow.separation_of_duties'`).Scan(&value); {
	case err == nil:
		if err := json.Unmarshal(value, &policy); err != nil {
			return separationOfDuties{}, err
		}
		return policy, nil
	case errors.Is(err, pgx.ErrNoRows):
		return separationOfDuties{}, nil
	default:
		return separationOfDuties{}, err
	}
}

func (a *App) listWorkflows(w http.ResponseWriter, r *http.Request) {
	limit := parseLimit(r, 300)
	rows, err := a.db.Query(r.Context(), `SELECT id,name,object_type,enabled,conditions,steps,version,created_by,created_at,updated_at FROM workflow_definitions ORDER BY object_type,name,version DESC LIMIT $1`, limit+1)
	if err != nil {
		writeError(w, 500, "database_error", "워크플로를 조회하지 못했습니다")
		return
	}
	defer rows.Close()
	items := []map[string]any{}
	for rows.Next() {
		var id, name, typ string
		var enabled bool
		var conditions, steps []byte
		var version int
		var creator *string
		var created, updated any
		if err := rows.Scan(&id, &name, &typ, &enabled, &conditions, &steps, &version, &creator, &created, &updated); err != nil {
			logDB(err)
			writeError(w, 500, "database_error", "워크플로를 조회하지 못했습니다")
			return
		}
		var c, s any
		_ = json.Unmarshal(conditions, &c)
		_ = json.Unmarshal(steps, &s)
		items = append(items, map[string]any{"id": id, "name": name, "objectType": typ, "enabled": enabled, "conditions": c, "steps": s, "version": version, "createdBy": creator, "createdAt": created, "updatedAt": updated})
	}
	if err := rows.Err(); err != nil {
		logDB(err)
		writeError(w, 500, "database_error", "워크플로를 조회하지 못했습니다")
		return
	}
	items, truncated := truncate(items, limit)
	writeJSON(w, 200, map[string]any{"items": items, "limit": limit, "truncated": truncated})
}

// workflowObjectTypes is the vocabulary an approval rule's 대상 유형 is written
// in. It is not a caption: matchingWorkflow picks the rules that could route a
// submission with `WHERE object_type=$1` against the type name the route
// itself carries, so a rule filed under any other word is a rule that can
// never fire — and the submission it was written to hold falls through to
// `no_matching_workflow`, which is answered by stamping the object 승인 on the
// spot, with no approver and nothing in anyone's inbox.
//
// The eleven routed types are read out of objectRoutes rather than written
// down again: a type added there gets a submit endpoint the moment it is
// added, and an approval rule has to be writable for it. supplier_bank_change
// is the twelfth — changing a supplier's bank account opens a business object
// and submits it in the same statement instead of through a route of its own,
// and the rule installed with the schema is written for it.
//
// Nothing checked this, and the admin form had already come off the list. Its
// 업무 유형 dropdown offered four names, and one of them — "supplier", shown as
// 공급업체 — is a word no submit path in the application uses: the rule was
// accepted, listed as 활성, and matched nothing, ever. The eight real types the
// dropdown left out are the worse half. 납품, 검수, 품질, 이슈, RFQ, RFP,
// Invoice and 지급 all carry a 승인 요청 button, and with no rule that could be
// written for them at all, every one of those submissions was approved the
// instant it was sent.
func workflowObjectTypes() []string {
	types := make([]string, 0, len(objectRoutes)+1)
	for _, route := range objectRoutes {
		types = append(types, route.objectType)
	}
	return append(types, "supplier_bank_change")
}

// validWorkflowSteps checks the steps an approval rule routes by, and numbers
// them, on the way in rather than at submit time.
//
// A rule's steps are not a caption either: submitObject copies them into
// workflow_instances.context, and from then on the list is the request. An
// approver only sees a request whose current step exists — listApprovals drops
// any instance whose current_step is past the end of the list — and
// workflowAction refuses to act on one, answering 409 invalid_workflow. So a
// rule saved with no steps, or with steps that are not a list of objects at
// all, does not fail when it is saved. It fails when the next submission
// matches it: the object is moved to 결재중, the approval is opened, and the
// request is then in nobody's inbox and cannot be approved, rejected or
// returned. It cannot be sent again either, because the open instance is what
// blocks a second submit. Nothing in the application can move that object
// again.
//
// createWorkflow checked all of this. updateWorkflow, the only other statement
// that writes the column, checked none of it and stored whatever arrived —
// which is the shape of edit this whole panel is for.
func validWorkflowSteps(w http.ResponseWriter, steps any) ([]map[string]any, bool) {
	var list []map[string]any
	encoded, err := json.Marshal(steps)
	if err != nil || json.Unmarshal(encoded, &list) != nil {
		writeError(w, 400, "validation_error", "승인 단계 형식이 올바르지 않습니다")
		return nil, false
	}
	if len(list) == 0 {
		writeError(w, 400, "validation_error", "승인 단계는 하나 이상이어야 합니다")
		return nil, false
	}
	for i, step := range list {
		if strings.TrimSpace(stringValue(step, "name")) == "" {
			writeError(w, 400, "validation_error", "각 승인 단계에는 이름이 필요합니다")
			return nil, false
		}
		step["order"] = i
	}
	return list, true
}

// workflowObjectTypeField describes the field an approval rule names its
// target type in.
func workflowObjectTypeField() enumField {
	return enumField{key: "objectType", label: "업무 유형", allowed: workflowObjectTypes()}
}

func (a *App) createWorkflow(w http.ResponseWriter, r *http.Request) {
	p, _ := principalFrom(r.Context())
	var in struct {
		Name       string           `json:"name"`
		ObjectType string           `json:"objectType"`
		Enabled    bool             `json:"enabled"`
		Conditions any              `json:"conditions"`
		Steps      []map[string]any `json:"steps"`
	}
	if err := decodeJSON(r, &in); err != nil {
		writeError(w, 400, "invalid_request", err.Error())
		return
	}
	if in.Name == "" || in.ObjectType == "" || len(in.Steps) == 0 {
		writeError(w, 400, "validation_error", "이름, 대상 유형, 승인 단계가 필요합니다")
		return
	}
	if !validEnum(w, in.ObjectType, workflowObjectTypeField()) {
		return
	}
	steps, ok := validWorkflowSteps(w, in.Steps)
	if !ok {
		return
	}
	in.Steps = steps
	if !validWorkflowConditions(w, in.Conditions) {
		return
	}
	var id string
	err := a.db.QueryRow(r.Context(), `INSERT INTO workflow_definitions(name,object_type,enabled,conditions,steps,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING id`, in.Name, in.ObjectType, in.Enabled, raw(in.Conditions), raw(in.Steps), p.ID).Scan(&id)
	if err != nil {
		writeError(w, 400, "save_failed", "워크플로를 저장하지 못했습니다")
		return
	}
	a.audit.record(r, "create", "workflow", id, nil, in)
	writeJSON(w, 201, map[string]any{"id": id})
}

name: CI

on:
  push:
    branches: [main]
  pull_request:

jobs:
  go:
    runs-on: ubuntu-latest
    services:
      postgres:
        # The integration tests need a real database: they exercise advisory
        # locks, partial unique indexes, trigram search and jsonpath, none of
        # which a fake would tell the truth about.
        image: postgres:16-alpine
        env:
          POSTGRES_PASSWORD: ci
        options: >-
          --health-cmd "pg_isready -U postgres"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 12
        ports:
          - 5432:5432
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-go@v5
        with:
          go-version-file: go.mod
          cache: true
      - name: gofmt
        run: |
          unformatted=$(gofmt -l internal cmd)
          if [ -n "$unformatted" ]; then
            echo "$unformatted"
            exit 1
          fi
      - run: go vet ./internal/... ./cmd/...
      - name: Prepare the test databases
        run: |
          # Three, because the migration and upgrade harnesses each need an
          # empty database of their own: one starts six replicas racing to
          # migrate, the other builds an older schema with data in it and
          # brings it forward. Both skip silently when their DSN is unset,
          # which is how they went unrun here for their whole life.
          PGPASSWORD=ci psql -h 127.0.0.1 -U postgres -c 'CREATE DATABASE vendra_ci'
          PGPASSWORD=ci psql -h 127.0.0.1 -U postgres -c 'CREATE DATABASE vendra_ci_migrate'
          PGPASSWORD=ci psql -h 127.0.0.1 -U postgres -c 'CREATE DATABASE vendra_ci_upgrade'
      - name: go test
        env:
          VENDRA_TEST_DSN: postgres://postgres:ci@127.0.0.1:5432/vendra_ci?sslmode=disable
          VENDRA_TEST_MIGRATE_DSN: postgres://postgres:ci@127.0.0.1:5432/vendra_ci_migrate?sslmode=disable
          VENDRA_TEST_UPGRADE_DSN: postgres://postgres:ci@127.0.0.1:5432/vendra_ci_upgrade?sslmode=disable
        run: go test ./internal/... -count=1

  web:
    runs-on: ubuntu-latest
    defaults:
      run:
        working-directory: web
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: web/package-lock.json
      - run: npm ci --ignore-scripts
      - run: npx tsc -b --noEmit
      - run: npx eslint src --max-warnings 0
      - run: npm test
      - run: npm run build
